SELECT
    SUM(current_output) AS currentOutput,
    SUM(planned_production) AS plannedProduction
FROM
    order_main
WHERE
    del_flag='0'
    and company_id= #{companyId}
    and order_year = #{orderYear}
    and order_month = #{orderMonth}
